// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX, Log} from "../src/MONEY_BOX.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MONEY_BOX c;
    Attacker attacker;

    function setUp() public {
        c = new MONEY_BOX();
        c.SetLogFile(address(new Log()));
    }

    function testFuzz_property(uint256 amount, uint256 minSum, uint256 newVal) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0);
        minSum = bound(minSum, 0, type(uint128).max);
        amount = bound(amount, minSum, type(uint128).max);
        newVal = bound(newVal, 0, type(uint128).max);

        c.SetMinSum(minSum);

        attacker = new Attacker(c, newVal);

        vm.warp(10);
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.Put{value: amount}(0);

        vm.warp(11);
        vm.prank(address(attacker));
        c.Collect(amount);

        assertTrue(c.MinSum() == minSum);
    }
}

contract Attacker {
    MONEY_BOX private c;
    uint256 private newVal;
    bool private entered;

    constructor(MONEY_BOX _c, uint256 _newVal) {
        c = _c;
        newVal = _newVal;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.SetMinSum(newVal);
        }
    }
}
